// Sync window for the poller. Settings come from Workflow Config.
const cfg = $('Workflow Config').first().json;
const state = $getWorkflowStaticData('global'); // only persists on production (trigger) runs, not manual test runs
const now = new Date();
let from;
let fromSource;

if (cfg.windowStartOverride) {
  from = new Date(cfg.windowStartOverride);
  if (isNaN(from.getTime())) {
    throw new Error('windowStartOverride is not a valid ISO date-time: ' + cfg.windowStartOverride);
  }
  fromSource = 'override';
} else if (state.lastWindowEnd) {
  from = new Date(new Date(state.lastWindowEnd).getTime() - Number(cfg.overlapMinutes) * 60000);
  fromSource = 'watermark';
} else {
  from = new Date(now.getTime() - Number(cfg.initialLookbackMinutes) * 60000);
  fromSource = 'initial lookback';
}
if (from.getTime() >= now.getTime()) {
  throw new Error('Sync window starts in the future (' + from.toISOString() + '). Check windowStartOverride and the saved watermark.');
}

return [{ json: {
  windowFrom: from.toISOString(),
  windowTo: now.toISOString(),
  windowFromMs: from.getTime(), // HubSpot search filters take epoch milliseconds
  fromSource,
} }];

