// Turns the five HubSpot "changed since" searches into ONE item per changed record, shaped exactly like
// the webhook payload the HubSpot -> Simpro router already understands:
//   { body: [ { objectId, objectTypeId, subscriptionType } ] }
const win = $('Build Sync Window').first().json;

const SOURCES = [
  { node: 'Fetch Changed Companies',   type: 'Company', objectTypeId: '0-2',   subscriptionType: 'company.propertyChange' },
  { node: 'Fetch Changed Sites',       type: 'Site',    objectTypeId: '0-420', subscriptionType: 'object.propertyChange' },
  { node: 'Fetch Changed Contacts',    type: 'Contact', objectTypeId: '0-1',   subscriptionType: 'contact.propertyChange' },
  { node: 'Fetch Changed Quote Deals', type: 'Quote',   objectTypeId: '0-3',   subscriptionType: 'deal.propertyChange' },
  { node: 'Fetch Changed Job Deals',   type: 'Job',     objectTypeId: '0-3',   subscriptionType: 'deal.propertyChange' },
];

const records = [];
const counts = {};

for (const s of SOURCES) {
  const pages = $(s.node).all().map(i => i.json); // one item per page of results
  const seen = new Set();
  let rows = 0;
  let reportedTotal = null;

  for (const page of pages) {
    if (!Array.isArray(page.results)) {
      throw new Error(s.node + ': expected a results array from HubSpot, got ' + JSON.stringify(page).slice(0, 300));
    }
    if (reportedTotal === null && page.total !== undefined) reportedTotal = Number(page.total);
    for (const row of page.results) {
      if (row === null || typeof row !== 'object' || !row.id) {
        throw new Error(s.node + ': a returned record has no id.');
      }
      rows++;
      if (seen.has(row.id)) continue;
      seen.add(row.id);
      records.push({ json: {
        hasRecords: true,
        body: [{ objectId: Number(row.id), objectTypeId: s.objectTypeId, subscriptionType: s.subscriptionType }],
        meta: { source: 'poll', type: s.type, windowFrom: win.windowFrom, windowTo: win.windowTo },
      } });
    }
  }

  // The page cap (50 x 200 = HubSpot's 10,000 search limit) stops silently - fail loudly instead of syncing a partial window.
  if (reportedTotal !== null && rows < reportedTotal) {
    throw new Error(s.node + ': read ' + rows + ' of ' + reportedTotal + ' changed records (HubSpot search limit reached). '
      + 'Shorten the window (windowStartOverride) and run again.');
  }
  counts[s.type] = seen.size;
}

if (records.length === 0) {
  return [{ json: { hasRecords: false, windowFrom: win.windowFrom, windowTo: win.windowTo, counts } }];
}
return records;

